 ov.innerHTML='<div style="background:#fff;width:min(520px,96vw);border-radius:16px;overflow:hidden"><div style="padding:15px 18px;background:#0f172a;color:#fff;display:flex;justify-content:space-between;align-items:center"><div><strong>Abrir anticipo · '+h(a.folio)+'</strong><div style="font-size:10px;color:#cbd5e1;margin-top:3px">Requiere autorización de un usuario con permiso para reabrir anticipos.</div></div><button id="ccAntReopenClose" type="button" style="background:none;border:0;color:#fff;font-size:22px;cursor:pointer">×</button></div><form id="ccAntReopenForm" style="padding:18px"><div class="cc-config-alert" style="margin-bottom:12px"><strong>Anticipo cerrado.</strong> Mientras permanezca cerrado no se pueden registrar comprobaciones, extras, devoluciones ni generar nuevos enlaces.</div><div class="cc-field"><label>Correo del usuario autorizador *</label><input name="email" type="email" autocomplete="username" required></div><div class="cc-field" style="margin-top:9px"><label>Contraseña *</label><input name="password" type="password" autocomplete="current-password" required></div><div class="cc-field" style="margin-top:9px"><label>Motivo de reapertura</label><textarea name="motivo" rows="3" placeholder="Motivo por el que se requiere abrir nuevamente el anticipo"></textarea></div><div id="ccAntReopenMsg" style="margin-top:10px"></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:13px"><button type="button" class="cc-btn cc-btn-light" id="ccAntReopenCancel">Cancelar</button><button type="submit" class="cc-btn cc-btn-primary" id="ccAntReopenSubmit"><i class="fa-solid fa-lock-open mr-1"></i>Abrir anticipo</button></div></form></div>';
